//! Golden differential tests: fixtures generated by `go run -mod=vendor ./hack/golden/ignition`
//! from the Go implementation; the Rust port must reproduce every output byte-for-byte.

use std::path::PathBuf;

use apis::dpf::provisioning::v1alpha1::{DPUFlavor, DPUFlavorOVS, DPUFlavorSpec};
use ignition::content::{self, ContentProvider};
use ignition::resources::{common, live, target};
use ignition::types::{Config, Unit};
use serde_json::Value;

fn fixture(name: &str) -> Vec<Value> {
    let p = PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures")
        .join(name);
    let s = std::fs::read_to_string(&p).unwrap_or_else(|e| panic!("{}: {e}", p.display()));
    serde_json::from_str(&s).unwrap()
}

fn s<'a>(v: &'a Value, k: &str) -> &'a str {
    v[k].as_str().unwrap_or_else(|| panic!("missing {k}"))
}

fn decode(s: &str) -> Config {
    ignition::unmarshal_config(s.as_bytes()).unwrap_or_else(|e| panic!("decode {s}: {e}"))
}

fn raw(c: &Config) -> String {
    String::from_utf8(ignition::marshal_config(c)).unwrap()
}

fn err_str<T>(r: &anyhow::Result<T>) -> String {
    match r {
        Ok(_) => String::new(),
        Err(e) => e.to_string(),
    }
}

fn b64(s: &str) -> Vec<u8> {
    gocompat::base64::decode_string(s.as_bytes()).unwrap()
}

#[test]
fn configs_marshal_encode_gzip_validate() {
    let mut failures = Vec::new();
    for c in fixture("configs.json") {
        let name = s(&c, "name");
        let cfg = decode(s(&c, "input"));
        let mut check = |what: &str, got: String, want: &str| {
            if got != want {
                failures.push(format!("{name} {what}:\n  got:  {got:?}\n  want: {want:?}"));
            }
        };
        check("raw", raw(&cfg), s(&c, "raw"));
        check(
            "marshal",
            String::from_utf8(ignition::marshal_json(&cfg).unwrap()).unwrap(),
            s(&c, "marshal"),
        );
        if let Some(e) = c["encode"].as_str() {
            check("encode", ignition::encode_ignition(&cfg).unwrap(), e);
        }
        check(
            "validate",
            err_str(&ignition::validate_config(Some(&cfg))),
            s(&c, "validate"),
        );
        let rpt = ignition::validate_with_context(&cfg);
        check("report", rpt.to_string(), s(&c, "report"));
        let full: String = rpt
            .entries
            .iter()
            .map(|e| {
                let k = match e.kind {
                    ignition::validate::Kind::Error => 0,
                    ignition::validate::Kind::Warn => 1,
                    ignition::validate::Kind::Info => 2,
                };
                format!("{k}|{}|{}\n", e.context, e.message)
            })
            .collect();
        check("report_full", full, s(&c, "report_full"));
        let mut g = cfg.clone();
        let r = ignition::gzip_ignition_files(&mut g);
        check("gzip_err", err_str(&r), s(&c, "gzip_err"));
        check("gzip", raw(&g), s(&c, "gzip"));
    }
    assert!(
        failures.is_empty(),
        "{} failures:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn unmarshal_config_matches_go() {
    let mut failures = Vec::new();
    for c in fixture("unmarshal.json") {
        let input = s(&c, "input");
        let (got_raw, got_err) = match ignition::unmarshal_config(input.as_bytes()) {
            Ok(cfg) => (raw(&cfg), String::new()),
            Err(e) => (String::new(), e.to_string()),
        };
        if got_raw != s(&c, "raw") || got_err != s(&c, "err") {
            failures.push(format!(
                "{input:?}:\n  got:  {got_raw:?} / {got_err:?}\n  want: {:?} / {:?}",
                s(&c, "raw"),
                s(&c, "err")
            ));
        }
    }
    assert!(failures.is_empty(), "{}", failures.join("\n"));
}

#[test]
fn decode_ignition_matches_go() {
    for c in fixture("decode_ignition.json") {
        let input = s(&c, "input");
        let r = ignition::decode_ignition(input);
        assert_eq!(err_str(&r), s(&c, "err"), "{input:?}");
        if let Ok(cfg) = r {
            assert_eq!(raw(&cfg), s(&c, "raw"), "{input:?}");
        }
    }
}

#[test]
fn merge_struct_transcribe_matches_go() {
    let mut failures = Vec::new();
    for (i, c) in fixture("merge.json").iter().enumerate() {
        let got = raw(&ignition::merge_configs(
            &decode(s(c, "parent")),
            &decode(s(c, "child")),
        ));
        if got != s(c, "result") {
            failures.push(format!(
                "case {i}:\n parent: {}\n child:  {}\n got:    {got}\n want:   {}",
                s(c, "parent"),
                s(c, "child"),
                s(c, "result")
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} failures:\n{}",
        failures.len(),
        failures.join("\n")
    );
}

#[test]
fn merge_flavor_config_files_matches_go() {
    for c in fixture("merge_flavor.json") {
        let name = s(&c, "name");
        let spec: DPUFlavorSpec = serde_json::from_str(s(&c, "spec")).unwrap();
        let mut base = decode(s(&c, "base"));
        let r = ignition::merge_flavor_config_files(&mut base, &spec);
        assert_eq!(err_str(&r), s(&c, "err"), "{name}");
        assert_eq!(raw(&base), s(&c, "result"), "{name}");
    }
}

