#[test]
fn add_flavor_ovs_script_matches_go() {
    for c in fixture("ovs.json") {
        let mut cfg = ignition::new_empty_ignition("3.4.0");
        let spec = DPUFlavorSpec {
            ovs: DPUFlavorOVS {
                raw_config_script: s(&c, "arg").to_string(),
                ..Default::default()
            },
            ..Default::default()
        };
        ignition::add_flavor_ovs_script(&mut cfg, &spec);
        assert_eq!(raw(&cfg), s(&c, "result"));
    }
}

#[test]
fn encode_gzip_file_and_url_encode_match_go() {
    for c in fixture("encode.json") {
        let input = b64(s(&c, "arg"));
        let got = match s(&c, "name") {
            "gzip" => {
                let r = ignition::encode_gzip_file(&input).unwrap();
                format!("{}|{}", r.source.unwrap(), r.compression.unwrap())
            }
            _ => ignition::url_encode(std::str::from_utf8(&input).unwrap_or("\u{0}\u{fffd}\u{7f}")),
        };
        if s(&c, "name") == "urlencode" && std::str::from_utf8(&input).is_err() {
            continue; // Rust strings cannot hold invalid UTF-8
        }
        assert_eq!(got, s(&c, "result"), "{:?}", s(&c, "arg"));
    }
}

#[test]
fn add_dpu_flavor_yaml_json_match_go() {
    for c in fixture("flavor.json") {
        let name = s(&c, "name");
        let flavor: DPUFlavor = serde_json::from_str(s(&c, "flavor")).unwrap();
        let mut y = ignition::new_empty_ignition("3.4.0");
        ignition::add_dpu_flavor_yaml(&mut y, &flavor).unwrap();
        assert_eq!(raw(&y), s(&c, "yaml"), "{name} yaml");
        let mut j = ignition::new_empty_ignition("3.4.0");
        ignition::add_dpu_flavor_json(&mut j, &flavor).unwrap();
        assert_eq!(raw(&j), s(&c, "json"), "{name} json");
    }
}

#[test]
fn content_providers_match_go() {
    type NewProvider = fn(bool) -> content::EmbeddedProvider;
    let providers: [(&str, NewProvider); 3] = [
        ("common", common::new_provider),
        ("live", live::new_provider),
        ("target", target::new_provider),
    ];
    let cases = fixture("content.json");
    let find = |name: &str| {
        cases
            .iter()
            .find(|c| s(c, "name") == name)
            .unwrap_or_else(|| panic!("{name}"))
    };
    let check = |name: &str, cfg: &Config| {
        let c = find(name);
        assert_eq!(raw(cfg), s(c, "result"), "{name}");
        assert_eq!(
            String::from_utf8(ignition::marshal_json(cfg).unwrap()).unwrap(),
            s(c, "marshal"),
            "{name}"
        );
        assert_eq!(
            ignition::encode_ignition(cfg).unwrap(),
            s(c, "encode"),
            "{name}"
        );
    };
    for (pname, new) in providers {
        for zt in [false, true] {
            let p = new(zt);
            let mut cfg = ignition::new_empty_ignition("3.4.0");
            content::add_content(&mut cfg, &p).unwrap();
            check(&format!("{pname}_zt_{zt}"), &cfg);
            let mut cfg = ignition::new_empty_ignition("");
            content::add_files(&mut cfg, &p).unwrap();
            check(&format!("{pname}_files_zt_{zt}"), &cfg);
            let mut cfg = ignition::new_empty_ignition("3.2.0");
            content::add_links(&mut cfg, &p).unwrap();
            check(&format!("{pname}_links_zt_{zt}"), &cfg);
            let mut cfg = ignition::new_empty_ignition("3.4.0");
            content::add_systemd_units(&mut cfg, &p).unwrap();
            check(&format!("{pname}_units_zt_{zt}"), &cfg);
        }
    }
    let mut cfg = ignition::new_empty_ignition("3.4.0");
    content::add_kernel_args(&mut cfg);
    content::add_kernel_args(&mut cfg);
    check("kernel_args", &cfg);

    for zt in [false, true] {
        let mut t = ignition::new_empty_ignition("3.4.0");
        content::add_content(&mut t, &target::new_provider(zt)).unwrap();
        let (name, unit) = target::render_dpu_agent_service_unit(zt).unwrap();
        let mut u = Unit::new(name);
        u.enabled = ignition::ptr(true);
        u.contents = Some(unit);
        ignition::units_mut(&mut t).push(u);
        content::add_content(&mut t, &common::new_provider(zt)).unwrap();
        check(&format!("target_full_zt_{zt}"), &t);
        ignition::gzip_ignition_files(&mut t).unwrap();
        check(&format!("target_full_gzip_zt_{zt}"), &t);
    }
}

#[test]
fn render_dpu_agent_service_unit_matches_go() {
    for c in fixture("dpu_agent_unit.json") {
        let zt = c["zero_trust"].as_bool().unwrap();
        let (name, contents) = target::render_dpu_agent_service_unit(zt).unwrap();
        assert_eq!(name, s(&c, "name"));
        assert_eq!(contents, s(&c, "contents"), "zero_trust={zt}");
    }
}

/// The generated embedded systemd listings mirror Go's `fs.ReadDir` of `systemd/*`.
#[test]
fn embedded_systemd_dirs_match_filesystem() {
    let root = PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("resources");
    for (name, dir) in [
        ("common", &ignition::resources::COMMON_SYSTEMD),
        ("live", &ignition::resources::LIVE_SYSTEMD),
        ("target", &ignition::resources::TARGET_SYSTEMD),
    ] {
        let mut want: Vec<(String, Vec<u8>)> = std::fs::read_dir(root.join(name).join("systemd"))
            .unwrap()
            .map(|e| e.unwrap())
            .filter(|e| e.file_type().unwrap().is_file())
            .map(|e| {
                (
                    e.file_name().to_string_lossy().into_owned(),
                    std::fs::read(e.path()).unwrap(),
                )
            })
            .collect();
        want.sort();
        let units = content::load_systemd_units(dir).unwrap();
        let got: Vec<(String, Vec<u8>)> = units.into_iter().map(|u| (u.name, u.contents)).collect();
        assert_eq!(got, want, "{name}");
        let p = content::EmbeddedProvider {
            systemd_fs: Some(dir),
            ..Default::default()
        };
        assert_eq!(p.get_systemd_units().unwrap().len(), dir.entries.len());
    }
}
